/* ==UserStyle==
@name Cinny Catppuccin
@namespace github.com/catppuccin/userstyles/styles/cinny
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/cinny
@version 2026.08.16
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/cinny/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Acinny
@description Soothing pastel theme for Cinny
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("cinny.in") {
  @import url("https://prismjs.catppuccin.com/variables.important.css");
  code .token {
    opacity: 1 !important;
  }

  :root,
  .silver-theme {
    #catppuccin(@lightFlavor);
  }

  .dark-theme,
  .butter-theme {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();
    #lib.css-variables();

    /* Legacy user colors */
    --mx-uc-1: @blue;
    --mx-uc-2: @pink;
    --mx-uc-3: @teal;
    --mx-uc-4: @red;
    --mx-uc-5: @peach;
    --mx-uc-6: @sky;
    --mx-uc-7: @mauve;
    --mx-uc-8: @green;

    body.oq6d071w,
    &._15q3ngn0,
    &._15q3ngn1,
    &._15q3ngn2 {
      --oq6d070: @mantle;
      --oq6d071: @base;
      --oq6d072: @surface0;
      --oq6d073: @surface1;
      --oq6d074: @text;
      --oq6d075: @base;
      --oq6d076: @surface0;
      --oq6d077: @surface1;
      --oq6d078: @surface2;
      --oq6d079: @text;
      --oq6d07a: @mantle;
      --oq6d07b: @base;
      --oq6d07c: @surface0;
      --oq6d07d: @surface1;
      --oq6d07e: @text;

      --oq6d07f: @subtext0;
      --oq6d07g: @overlay2;
