      --oq6d071t: fade(@text, 50%);
      --oq6d071u: @crust;
      --oq6d071v: fade(@crust, 60%);
    }

    /* Search results */
    ._1m2qi7rq {
      background-color: @accent;
      color: @base;
    }

    /* Footer */
    .footer {
      .text-s1,
      .text-h2,
      a {
        color: @text;
      }

      .footer__creator,
      .footer__menu-container .text-b3 {
